import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Object3D } = ctx.THREE;

  const group = new Group();
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Create plane geometry (512x320 pixels @ ~2 units/screen)
  const planeGeo = new PlaneGeometry(3.2, 2.0);
  const planeMat = new MeshBasicNodeMaterial({
    side: ctx.THREE.FrontSide,
    transparent: true,
  });

  const planeMesh = new Mesh(planeGeo, planeMat);
  group.add(planeMesh);

  // Load the feature card image
  const imageLoadPromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((imgTex) => {
        imgTex.flipY = false;
        planeMat.colorNode = texture(imgTex, uv());
        planeMat.needsUpdate = true;
      })
    : Promise.resolve();

  // Create headline text: "Collection" (96px @ 400 weight)
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textContent.find((item) => item.role === 'headline') || { text: 'Collection' };
  const headlineText = ctx.fontAtlas.createText(String(headlineItem.text), {
    fontSize: 96,
    color: config.intent?.visualSpec?.colors?.paper || '#e8ecf2',
    align: 'center',
  });
  headlineText.position.set(0, 1.2, 0.1);
  group.add(headlineText);

  // Cleanup handler
  group.userData.cleanup = () => {
    planeGeo.dispose();
    planeMat.dispose();
    if (planeMesh.geometry) planeMesh.geometry.dispose();
    if (planeMesh.material) planeMesh.material.dispose();
  };

  group.userData.handlers = {};

  return group;
}
